88	void launch_lion_step(
89	    torch::Tensor& param,
90	    torch::Tensor& exp_avg,
91	    const torch::Tensor& grad,
92	    float lr, float beta1, float beta2, float wd
93	) {
94	    const int64_t N = param.numel();
95	    if (N == 0) return;
96	
97	    auto stream = at::cuda::getCurrentCUDAStream().stream();
98	
99	    // §6.1: keep the Lion momentum buffer L2-resident across the step.
100	    prim::L2PersistScope l2(stream, exp_avg.data_ptr(), exp_avg.nbytes());
101	
102	    const int block = SG_TUNED_BLOCK_SIZE;
103	    // Clamp the grid in int64 (N can exceed 2^31) then cast the grid dim to int.
104	    const int grid = static_cast<int>(
105	        std::min<int64_t>(65535, (N + block - 1) / block));
106	
107	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
108	                          grad.scalar_type() == torch::kFloat32;
109	
110	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
111	        prim::is_vec4_alignable(param.data_ptr(), N) &&
112	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
113	        const int64_t N4 = N / 4;
114	        const int grid4 = static_cast<int>(
115	            std::min<int64_t>(65535, (N4 + block - 1) / block));
116	        lion_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
117	            reinterpret_cast<float4*>(param.data_ptr<float>()),
118	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
119	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
120	            lr, beta1, beta2, wd, N4);
121	        SG_LAUNCH_CHECK(stream);
122	        return;
123	    }
124	
125	    AT_DISPATCH_FLOATING_TYPES_AND2(
126	        at::ScalarType::Half, at::ScalarType::BFloat16,
127	        param.scalar_type(), "lion_step", [&] {
128	            lion_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
129	                <<<grid, block, 0, stream>>>(
130	                param.data_ptr<scalar_t>(),
131	                exp_avg.data_ptr<float>(),
132	                grad.data_ptr<scalar_t>(),
133	                lr, beta1, beta2, wd, N);
134	            SG_LAUNCH_CHECK(stream);
135	        });
136	}
